//Follow this doc for HTML and REST API integration: https://hyperswitch.io/docs/sdkIntegrations/unifiedCheckoutWeb/restAPIBackendAndHTMLFrontend
// Update your publishable key here

const hyper = Hyper("HYPERSWITCH_PUBLISHABLE_KEY");

const items = [{ id: "xl-tshirt" }];

async function initialize() {
  // For demo purpose we are calling the hyperswitch API directly here, but in actual setup this should be backend call to your server and call the hyperswitch API internally with your API key
  const response = await fetch("/create-payment", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ items }),
  });
  const {
    client_secret
  } = await response.json();

  // You can change the apperance of the SDK by adding field here
  const appearance = {
    // theme: "midnight",
  };

  widgets = hyper.widgets({
    appearance,
    clientSecret: client_secret
  });

  const unifiedCheckoutOptions = {
    layout: "tabs",
    wallets: {
      walletReturnUrl: "https://example.com/complete",
      //Mandatory parameter for Wallet Flows such as Googlepay, Paypal and Applepay
    },
  };

  const unifiedCheckout = widgets.create("payment", unifiedCheckoutOptions);
  unifiedCheckout.mount("#unified-checkout");
}
initialize();

async function handleSubmit(e) {
  setLoading(true);
  const { error, data, status } = await hyper.confirmPayment({
    widgets,
    confirmParams: {
      // Make sure to change this to your payment completion page
      return_url: "https://example.com/complete",
    },
  });

  // This point will only be reached if there is an immediate error occurring while confirming the payment. Otherwise, your customer will be redirected to your `return_url`.

  // For some payment flows such as Sofort, iDEAL, your customer will be redirected to an intermediate page to complete authorization of the payment, and then redirected to the `return_url`.

  if (error && error.type === "validation_error") {
    showMessage(error.message);
  }
  else if (status === "succeeded") {
    addClass("#hypers-sdk", "hidden")
    removeClass("#orderSuccess", "hidden")
  }
  else {
    showMessage("An unexpected error occurred.");
  }

  setLoading(false);
}

// Fetches the payment status after payment submission
async function checkStatus() {
  const clientSecret = new URLSearchParams(window.location.search).get(
    "payment_intent_client_secret"
  );

  if (!clientSecret) {
    return;
  }

  const { payment } = await hyper.retrievePayment(clientSecret);

  switch (payment.status) {
    case "succeeded":
      showMessage("Payment succeeded!");
      break;
    case "processing":
      showMessage("Your payment is processing.");
      break;
    case "requires_payment_method":
      showMessage("Your payment was not successful, please try again.");
      break;
    default:
      showMessage("Something went wrong.");
      break;
  }
}

function setLoading(showLoader) {
  if (showLoader) {
    show('.spinner');
    hide('#button-text');
  }
  else {
    hide('.spinner');
    show('#button-text');
  }
}

function show(id) {
  removeClass(id, 'hidden');
}
function hide(id) {
  addClass(id, 'hidden');
}

function showMessage(msg) {
  show('#payment-message');
  addText('#payment-message', msg);
}

function addText(id, msg) {
  var element = document.querySelector(id);
  element.innerText = msg;
}

function addClass(id, className) {
  var element = document.querySelector(id);
  element.classList.add(className);
}

function removeClass(id, className) {
  var element = document.querySelector(id);
  element.classList.remove(className);
}

function retryPayment() {
  hide('#orderSuccess');
  show('.Container');
  initialize();
}

function showSDK(e) {
  hide('.Container');
  show('#hypers-sdk');
};

package com.hyperswitch.sample;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStream;

import java.net.HttpURLConnection;
import java.net.URL;

import java.nio.file.Paths;

import static spark.Spark.post;
import static spark.Spark.staticFiles;
import static spark.Spark.port;

import org.json.JSONObject;

public class server {

  public static void main(String[] args) {

    port(4242);

    staticFiles.externalLocation(Paths.get("public").toAbsolutePath().toString());

    post("/create-payment", (request, response) -> {

      response.type("application/json");

      /*
        If you have two or more “business_country” + “business_label” pairs configured in your Hyperswitch dashboard,
        please pass the fields business_country and business_label in this request body.
        For accessing more features, you can check out the request body schema for payments-create API here :
        https://api-reference.hyperswitch.io/docs/hyperswitch-api-reference/60bae82472db8-payments-create
      */

      String payload = "{ \"amount\": 100, \"currency\": \"USD\", \"customer_id\": \"hyperswitch_customer\" }";

      String response_string = createPayment(payload);
      JSONObject response_json = new JSONObject(response_string);

      String client_secret = response_json.getString("client_secret");

      JSONObject final_response = new JSONObject();
      final_response.put("client_secret", client_secret);

      return final_response;

    });

  }

  private static String createPayment(String payload) {

    try {

      String HYPER_SWITCH_API_KEY = "HYPERSWITCH_API_KEY";
      String HYPER_SWITCH_API_BASE_URL = "https://sandbox.hyperswitch.io/payments";

      URL url = new URL(HYPER_SWITCH_API_BASE_URL);
      HttpURLConnection conn = (HttpURLConnection) url.openConnection();

      conn.setRequestMethod("POST");
      conn.setRequestProperty("Content-Type", "application/json");
      conn.setRequestProperty("Accept", "application/json");
      conn.setRequestProperty("api-key", HYPER_SWITCH_API_KEY);
      conn.setDoOutput(true);

      try (OutputStream os = conn.getOutputStream()) {
        byte[] input = payload.getBytes("utf-8");
        os.write(input, 0, input.length);
      }

      int responseCode = conn.getResponseCode();

      if (responseCode == HttpURLConnection.HTTP_OK) {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(conn.getInputStream(), "utf-8"))) {
          StringBuilder response = new StringBuilder();
          String responseLine;
          while ((responseLine = br.readLine()) != null) {
            response.append(responseLine.trim());
          }
          return response.toString();
        }
      } else {
        return "HTTP request failed with response code: " + responseCode;
      }
    } catch (IOException e) {
      return e.getMessage();
    }

  }

}
